repo.tickets.py:
"""Ticket records."""


class Ticket:
    def __init__(self, team, hours):
        self.team = team
        self.hours = hours

    def __repr__(self):
        return "Ticket(%r, %r)" % (self.team, self.hours)


ROWS = [('core', 17), ('ops', 16), ('ops', 43), ('ops', 34), ('web', 22), ('web', 56)]


def load_tickets():
    """Yield the stored tickets one at a time."""
    for team, hours in ROWS:
        yield Ticket(team, hours)

repo.labels.py:
"""Labels for tickets."""


def label_tickets(names, tickets):
    """Return (lookup, lines): a name -> hours dict and one 'name: hours' line per ticket."""
    pairs = zip(names, (x.hours for x in tickets))
    lookup = dict(pairs)
    lines = ["%s: %s" % (name, value) for name, value in pairs]
    return lookup, lines


def name_list(names):
    """Return the names joined by commas."""
    return ", ".join(names)

